compile.workshop:
variables {
    global:
        0: horizontalAngle
}

rule ("horizontal facing angle") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(horizontalAngle, Horizontal Facing Angle Of(Event Player));
    }
}

